export const DeviceServiceServiceName = "fleet_console_prototype.apipb.DeviceService";
export class DeviceServiceClientImpl implements DeviceService {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || DeviceServiceServiceName;
    this.rpc = rpc;
    this.GetDevice = this.GetDevice.bind(this);
    this.ListDevices = this.ListDevices.bind(this);
  }
  GetDevice(request: GetDeviceRequest): Promise<Device> {
    const data = GetDeviceRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetDevice", data);
    return promise.then((data) => Device.decode(new BinaryReader(data)));
  }

  ListDevices(request: ListDevicesRequest): Promise<ListDevicesResponse> {
    const data = ListDevicesRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "ListDevices", data);
    return promise.then((data) => ListDevicesResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

function isObject(value: any): boolean {
  return typeof value === "object" && value !== null;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}
